-- SoundConnect Studio domain additive rollout.
--
-- Prerequisites:
--   * Reconcile this script with an authoritative schema-only dump before production.
--   * Run with a role allowed to install/own btree_gist, or pre-provision that extension.
--   * Run psql with ON_ERROR_STOP=1.
--
-- The migration is intentionally additive and rerunnable. It does not import Flutter
-- mock data. UUIDs are generated by the application; deterministic UUID literals are
-- used only for global seed rows.

BEGIN;

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------------------
-- Stable public user code
-- ---------------------------------------------------------------------------

ALTER TABLE tbl_user
    ADD COLUMN IF NOT EXISTS public_code varchar(23);

DO $$
BEGIN
    IF (
        SELECT character_maximum_length
          FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'tbl_user'
           AND column_name = 'public_code'
    ) IS DISTINCT FROM 23 THEN
        DROP TRIGGER IF EXISTS trg_user_public_code ON tbl_user;
        ALTER TABLE tbl_user ALTER COLUMN public_code TYPE varchar(23);
    END IF;
END
$$;

ALTER TABLE tbl_user
    ALTER COLUMN public_code DROP DEFAULT;

CREATE OR REPLACE FUNCTION soundconnect_assign_user_public_code()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    candidate varchar(23);
BEGIN
    IF TG_OP = 'INSERT' AND (NEW.public_code IS NULL OR btrim(NEW.public_code) = '') THEN
        LOOP
            candidate := 'SC-' || upper(left(replace(gen_random_uuid()::text, '-', ''), 20));
            EXIT WHEN NOT EXISTS (SELECT 1 FROM tbl_user WHERE public_code = candidate);
        END LOOP;
        NEW.public_code := candidate;
    ELSIF TG_OP = 'UPDATE' AND (OLD.public_code IS NULL OR btrim(OLD.public_code) = '')
          AND (NEW.public_code IS NULL OR btrim(NEW.public_code) = '') THEN
        LOOP
            candidate := 'SC-' || upper(left(replace(gen_random_uuid()::text, '-', ''), 20));
            EXIT WHEN NOT EXISTS (SELECT 1 FROM tbl_user WHERE public_code = candidate);
        END LOOP;
        NEW.public_code := candidate;
    ELSIF TG_OP = 'UPDATE' AND NEW.public_code IS DISTINCT FROM OLD.public_code THEN
        RAISE EXCEPTION 'user public_code is immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_user_public_code_immutable';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_user_public_code ON tbl_user;
CREATE TRIGGER trg_user_public_code
BEFORE INSERT OR UPDATE OF public_code ON tbl_user
FOR EACH ROW
EXECUTE FUNCTION soundconnect_assign_user_public_code();

-- Assign through the same trigger used by future inserts. Random UUID-derived
-- values match the application format and are collision-checked before assignment.
UPDATE tbl_user
   SET public_code = NULL
 WHERE public_code IS NULL OR btrim(public_code) = '';

ALTER TABLE tbl_user
    ALTER COLUMN public_code SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_user_public_code
    ON tbl_user (public_code);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint
         WHERE conrelid = 'tbl_user'::regclass
           AND conname = 'ck_user_public_code_format'
    ) THEN
        ALTER TABLE tbl_user
            ADD CONSTRAINT ck_user_public_code_format
            CHECK (public_code ~ '^SC-[0-9A-F]{20}$');
    END IF;
END
$$;

-- ---------------------------------------------------------------------------
-- Studio profile additions and ordered Spotify catalog
-- ---------------------------------------------------------------------------

ALTER TABLE tbl_studio_profile
    ADD COLUMN IF NOT EXISTS time_zone varchar(64),
    ADD COLUMN IF NOT EXISTS version bigint,
    ADD COLUMN IF NOT EXISTS spotify_tracks jsonb,
    ADD COLUMN IF NOT EXISTS city_id uuid,
    ADD COLUMN IF NOT EXISTS district_id uuid,
    ADD COLUMN IF NOT EXISTS neighborhood_id uuid;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_studio_profile_city') THEN
        ALTER TABLE tbl_studio_profile ADD CONSTRAINT fk_studio_profile_city
            FOREIGN KEY (city_id) REFERENCES tbl_city (id) ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_studio_profile_district') THEN
        ALTER TABLE tbl_studio_profile ADD CONSTRAINT fk_studio_profile_district
            FOREIGN KEY (district_id) REFERENCES tbl_district (id) ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_studio_profile_neighborhood') THEN
        ALTER TABLE tbl_studio_profile ADD CONSTRAINT fk_studio_profile_neighborhood
            FOREIGN KEY (neighborhood_id) REFERENCES tbl_neighborhood (id) ON DELETE RESTRICT;
    END IF;
END
$$;

-- Existing legacy Studio profiles may not yet have a complete district and
-- neighborhood. New approved applications always provision all three values;
-- NOT NULL can be enforced in a later cleanup rollout after legacy backfill.

CREATE TABLE IF NOT EXISTS tbl_studio_applications (
    id uuid PRIMARY KEY,
    created_at timestamp,
    updated_at timestamp,
    applicant_id uuid NOT NULL,
    studio_name varchar(100) NOT NULL,
    studio_address varchar(255) NOT NULL,
    phone varchar(15) NOT NULL,
    city_id uuid NOT NULL,
    district_id uuid NOT NULL,
    neighborhood_id uuid NOT NULL,
    status varchar(16) NOT NULL,
    application_date timestamp NOT NULL,
    decision_date timestamp,
    reviewed_by_id uuid,
    rejection_reason varchar(500),
    CONSTRAINT fk_studio_application_applicant
        FOREIGN KEY (applicant_id) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_application_city
        FOREIGN KEY (city_id) REFERENCES tbl_city (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_application_district
        FOREIGN KEY (district_id) REFERENCES tbl_district (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_application_neighborhood
        FOREIGN KEY (neighborhood_id) REFERENCES tbl_neighborhood (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_application_reviewer
        FOREIGN KEY (reviewed_by_id) REFERENCES tbl_user (id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_studio_application_pending_applicant
    ON tbl_studio_applications (applicant_id)
    WHERE status = 'PENDING';

DROP INDEX IF EXISTS ix_studio_application_status_date;

CREATE INDEX IF NOT EXISTS ix_studio_application_status_date_id
    ON tbl_studio_applications (status, application_date, id);

CREATE INDEX IF NOT EXISTS ix_studio_application_applicant_date_id
    ON tbl_studio_applications (applicant_id, application_date DESC, id DESC);

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_studio_application_status') THEN
        ALTER TABLE tbl_studio_applications ADD CONSTRAINT ck_studio_application_status
            CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_studio_application_decision') THEN
        ALTER TABLE tbl_studio_applications ADD CONSTRAINT ck_studio_application_decision CHECK (
            (status = 'PENDING' AND decision_date IS NULL AND reviewed_by_id IS NULL AND rejection_reason IS NULL)
            OR (status = 'APPROVED' AND decision_date IS NOT NULL AND reviewed_by_id IS NOT NULL AND rejection_reason IS NULL)
            OR (status = 'REJECTED' AND decision_date IS NOT NULL AND reviewed_by_id IS NOT NULL AND rejection_reason IS NOT NULL)
        );
    END IF;
END
$$;

-- The new rejected-registration state is one character longer than the
-- previous longest UserStatus value. Widen only legacy bounded text columns;
-- unbounded text/varchar columns need no change and wider columns are kept.
DO $$
DECLARE
    user_status_data_type text;
    user_status_max_length integer;
BEGIN
    SELECT data_type, character_maximum_length
      INTO user_status_data_type, user_status_max_length
      FROM information_schema.columns
     WHERE table_schema = current_schema()
       AND table_name = 'tbl_user'
       AND column_name = 'status';

    IF user_status_data_type IN ('character varying', 'character')
       AND user_status_max_length IS NOT NULL
       AND user_status_max_length < 32 THEN
        ALTER TABLE tbl_user
            ALTER COLUMN status TYPE varchar(32) USING status::text;
    END IF;
END
$$;

-- Close legacy registration accounts whose most recent Studio application was
-- already rejected. Previously these users remained PENDING_STUDIO_REQUEST and
-- every later login incorrectly claimed that review was still in progress.
-- Active multi-role users are deliberately excluded by the status predicate.
UPDATE tbl_user applicant
   SET status = 'REJECTED_STUDIO_REQUEST',
       updated_at = CURRENT_TIMESTAMP
 WHERE applicant.status = 'PENDING_STUDIO_REQUEST'
   AND (
       SELECT application.status
         FROM tbl_studio_applications application
        WHERE application.applicant_id = applicant.id
        ORDER BY application.application_date DESC, application.id DESC
        LIMIT 1
   ) = 'REJECTED';

UPDATE tbl_studio_profile
   SET time_zone = 'Europe/Istanbul'
 WHERE time_zone IS NULL OR btrim(time_zone) = '';

UPDATE tbl_studio_profile
   SET version = 0
 WHERE version IS NULL;

UPDATE tbl_studio_profile
   SET spotify_tracks = '[]'::jsonb
 WHERE spotify_tracks IS NULL;

ALTER TABLE tbl_studio_profile
    ALTER COLUMN time_zone SET DEFAULT 'Europe/Istanbul',
    ALTER COLUMN time_zone SET NOT NULL,
    ALTER COLUMN version SET DEFAULT 0,
    ALTER COLUMN version SET NOT NULL,
    ALTER COLUMN spotify_tracks SET DEFAULT '[]'::jsonb,
    ALTER COLUMN spotify_tracks SET NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'tbl_studio_profile'::regclass
           AND conname = 'ck_studio_profile_time_zone_not_blank'
    ) THEN
        ALTER TABLE tbl_studio_profile
            ADD CONSTRAINT ck_studio_profile_time_zone_not_blank
            CHECK (btrim(time_zone) <> '');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'tbl_studio_profile'::regclass
           AND conname = 'ck_studio_profile_version_non_negative'
    ) THEN
        ALTER TABLE tbl_studio_profile
            ADD CONSTRAINT ck_studio_profile_version_non_negative
            CHECK (version >= 0);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'tbl_studio_profile'::regclass
           AND conname = 'ck_studio_profile_spotify_tracks_array'
    ) THEN
        ALTER TABLE tbl_studio_profile
            ADD CONSTRAINT ck_studio_profile_spotify_tracks_array
            CHECK (
                jsonb_typeof(spotify_tracks) = 'array'
                AND jsonb_array_length(spotify_tracks) <= 50
            );
    END IF;
END
$$;

CREATE TABLE IF NOT EXISTS studio_profile_spotify_tracks (
    studio_profile_id uuid NOT NULL,
    position integer NOT NULL,
    track_id varchar(64) NOT NULL,
    CONSTRAINT pk_studio_profile_spotify_tracks
        PRIMARY KEY (studio_profile_id, position),
    CONSTRAINT fk_studio_spotify_track_profile
        FOREIGN KEY (studio_profile_id)
        REFERENCES tbl_studio_profile (id)
        ON DELETE CASCADE,
    CONSTRAINT uk_studio_spotify_track
        UNIQUE (studio_profile_id, track_id),
    CONSTRAINT ck_studio_spotify_track_order
        CHECK (position BETWEEN 0 AND 49),
    CONSTRAINT ck_studio_spotify_track_id_not_blank
        CHECK (btrim(track_id) <> '')
);

-- ---------------------------------------------------------------------------
-- Global two-level backline catalog
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tbl_backline_category (
    id uuid NOT NULL,
    parent_id uuid,
    code varchar(96) NOT NULL,
    name varchar(160) NOT NULL,
    normalized_name varchar(160) NOT NULL,
    icon_key varchar(128),
    level smallint NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    active boolean NOT NULL DEFAULT true,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_backline_category PRIMARY KEY (id),
    CONSTRAINT fk_backline_category_parent
        FOREIGN KEY (parent_id)
        REFERENCES tbl_backline_category (id)
        ON DELETE RESTRICT,
    CONSTRAINT uk_backline_category_code UNIQUE (code),
    CONSTRAINT uk_backline_category_parent_normalized
        UNIQUE (parent_id, normalized_name),
    CONSTRAINT ck_backline_category_level CHECK (level IN (0, 1)),
    CONSTRAINT ck_backline_category_shape CHECK (
        (level = 0 AND parent_id IS NULL)
        OR (level = 1 AND parent_id IS NOT NULL)
    ),
    CONSTRAINT ck_backline_category_code_not_blank CHECK (btrim(code) <> ''),
    CONSTRAINT ck_backline_category_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_backline_category_normalized_name_not_blank
        CHECK (btrim(normalized_name) <> ''),
    CONSTRAINT ck_backline_category_sort_order CHECK (sort_order >= 0),
    CONSTRAINT ck_backline_category_version CHECK (version >= 0)
);

-- Hibernate-created local schemas contain the same non-null version column but
-- do not assign a database default. Seed statements must work against both the
-- canonical migration shape and that local-development shape.
ALTER TABLE tbl_backline_category
    ALTER COLUMN version SET DEFAULT 0;

CREATE UNIQUE INDEX IF NOT EXISTS uk_backline_root_normalized_name
    ON tbl_backline_category (normalized_name)
    WHERE parent_id IS NULL;

CREATE INDEX IF NOT EXISTS idx_backline_category_parent_active
    ON tbl_backline_category (parent_id, active, sort_order);

CREATE INDEX IF NOT EXISTS idx_backline_category_normalized
    ON tbl_backline_category (normalized_name);

CREATE OR REPLACE FUNCTION soundconnect_validate_backline_category_parent()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    parent_level smallint;
BEGIN
    IF NEW.parent_id = NEW.id THEN
        RAISE EXCEPTION 'backline category cannot be its own parent'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_two_levels';
    END IF;

    IF (NEW.parent_id IS NOT NULL OR NEW.level <> 0)
       AND EXISTS (
           SELECT 1 FROM tbl_backline_category child WHERE child.parent_id = NEW.id
       ) THEN
        RAISE EXCEPTION 'a category with children must remain a root category'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_two_levels';
    END IF;

    IF NEW.parent_id IS NULL THEN
        IF NEW.level <> 0 THEN
            RAISE EXCEPTION 'root backline category must have level 0'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_shape';
        END IF;
        RETURN NEW;
    END IF;

    SELECT level INTO parent_level
      FROM tbl_backline_category
     WHERE id = NEW.parent_id;

    IF parent_level IS NULL OR parent_level <> 0 OR NEW.level <> 1 THEN
        RAISE EXCEPTION 'backline catalog supports exactly two levels'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_two_levels';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_backline_category_parent ON tbl_backline_category;
CREATE TRIGGER trg_backline_category_parent
BEFORE INSERT OR UPDATE OF parent_id, level ON tbl_backline_category
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_backline_category_parent();

-- Seed normalization must not depend on the database cluster locale. This is
-- the SQL equivalent of BacklineCategoryNames: all Turkish I variants share
-- one ASCII-i uniqueness key, while the remaining Turkish uppercase letters
-- are lowered explicitly under the built-in C collation.
CREATE OR REPLACE FUNCTION soundconnect_normalize_backline_name(raw_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $$
    SELECT btrim(lower(
        translate(raw_name, 'İıÇĞÖŞÜ', 'Iiçğöşü') COLLATE "C"
    ));
$$;

-- Canonical reference catalog from backline-category-seed.json. A local
-- Hibernate bootstrap may have inserted these rows with generated UUIDs before
-- this migration runs. Adopt an existing root by code or normalized name so
-- its identity and every external reference remain untouched. Unrelated
-- administrator-created categories are neither updated nor removed.
WITH seed(id, code, name, icon_key, sort_order) AS (
    VALUES
    ('10000000-0000-0000-0000-000000000001'::uuid, 'drums-cymbals', 'Davul, Bateri & Zil', 'drum-kit', 0),
    ('10000000-0000-0000-0000-000000000002'::uuid, 'guitar-amplifiers', 'Gitar Amfileri', 'guitar-amps', 1),
    ('10000000-0000-0000-0000-000000000003'::uuid, 'bass-amplifiers', 'Bas Gitar Amfileri', 'bass-amps', 2),
    ('10000000-0000-0000-0000-000000000004'::uuid, 'piano-keyboards-synths', 'Piyano, Klavye & Synth', 'keyboards', 3),
    ('10000000-0000-0000-0000-000000000005'::uuid, 'percussion', 'Perküsyon', 'percussion', 4),
    ('10000000-0000-0000-0000-000000000006'::uuid, 'guitars-basses', 'Gitarlar & Baslar', 'guitars-basses', 5),
    ('10000000-0000-0000-0000-000000000007'::uuid, 'orchestral-instruments', 'Yaylılar & Orkestra Enstrümanları', 'orchestral-strings', 6),
    ('10000000-0000-0000-0000-000000000008'::uuid, 'dj-equipment', 'DJ Ekipmanları', 'dj', 7),
    ('10000000-0000-0000-0000-000000000009'::uuid, 'pro-audio-studio', 'Pro Audio & Stüdyo', 'pro-audio-studio', 8),
    ('10000000-0000-0000-0000-000000000010'::uuid, 'stage-backline-accessories', 'Sahne & Backline Aksesuarları', 'backline-accessories', 9)
)
INSERT INTO tbl_backline_category
    (id, parent_id, code, name, normalized_name, icon_key, level, sort_order, active)
SELECT seed.id,
       NULL,
       seed.code,
       seed.name,
       soundconnect_normalize_backline_name(seed.name),
       seed.icon_key,
       0,
       seed.sort_order,
       true
  FROM seed
 WHERE NOT EXISTS (
           SELECT 1
             FROM tbl_backline_category existing
            WHERE existing.code = seed.code
       )
   AND NOT EXISTS (
           SELECT 1
             FROM tbl_backline_category existing
            WHERE existing.parent_id IS NULL
              AND existing.normalized_name = soundconnect_normalize_backline_name(seed.name)
       )
ON CONFLICT DO NOTHING;

