INSERT INTO tbl_backline_category
    (id, parent_id, code, name, normalized_name, level, sort_order, active)
SELECT seed.id,
       parent.id,
       seed.code,
       seed.name,
       soundconnect_normalize_backline_name(seed.name),
       1,
       seed.sort_order,
       true
  FROM seed
  JOIN LATERAL (
       SELECT candidate.id
         FROM tbl_backline_category candidate
        WHERE candidate.parent_id IS NULL
          AND (
              candidate.code = seed.parent_code
              OR candidate.normalized_name = soundconnect_normalize_backline_name(seed.parent_name)
          )
        ORDER BY CASE WHEN candidate.code = seed.parent_code THEN 0 ELSE 1 END,
                 candidate.id
        LIMIT 1
  ) parent ON true
 WHERE NOT EXISTS (
           SELECT 1
             FROM tbl_backline_category existing
            WHERE existing.code = seed.code
       )
   AND NOT EXISTS (
           SELECT 1
             FROM tbl_backline_category existing
            WHERE existing.parent_id = parent.id
              AND existing.normalized_name = soundconnect_normalize_backline_name(seed.name)
       )
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- Rooms, ordered attachments, reservation requests and exclusive occupancy
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tbl_studio_room (
    id uuid NOT NULL,
    studio_profile_id uuid NOT NULL,
    client_request_id uuid NOT NULL,
    creation_payload_hash varchar(64) NOT NULL,
    slot_index integer NOT NULL,
    name varchar(100) NOT NULL,
    short_description varchar(60),
    capacity integer NOT NULL,
    minimum_capacity integer,
    hourly_price_minor bigint,
    currency varchar(3) NOT NULL DEFAULT 'TRY',
    reservation_approval_required boolean NOT NULL DEFAULT true,
    pending_reservation_approval_required boolean,
    reservation_approval_policy_effective_at timestamp with time zone,
    archived_at timestamp with time zone,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_room PRIMARY KEY (id),
    CONSTRAINT fk_studio_room_profile
        FOREIGN KEY (studio_profile_id)
        REFERENCES tbl_studio_profile (id)
        ON DELETE RESTRICT,
    CONSTRAINT uk_studio_room_profile_client_request
        UNIQUE (studio_profile_id, client_request_id),
    CONSTRAINT ck_studio_room_creation_payload_hash
        CHECK (creation_payload_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_studio_room_slot CHECK (slot_index BETWEEN 0 AND 9),
    CONSTRAINT ck_studio_room_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_studio_room_capacity CHECK (capacity BETWEEN 1 AND 100),
    CONSTRAINT ck_studio_room_minimum_capacity CHECK (
        minimum_capacity IS NULL
        OR minimum_capacity BETWEEN 1 AND capacity
    ),
    CONSTRAINT ck_studio_room_approval_policy_schedule CHECK (
        (pending_reservation_approval_required IS NULL
            AND reservation_approval_policy_effective_at IS NULL)
        OR
        (pending_reservation_approval_required IS NOT NULL
            AND reservation_approval_policy_effective_at IS NOT NULL)
    ),
    CONSTRAINT ck_studio_room_price CHECK (
        hourly_price_minor IS NULL OR hourly_price_minor BETWEEN 1 AND 100000000
    ),
    CONSTRAINT ck_studio_room_currency CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_studio_room_version CHECK (version >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_studio_room_active_slot
    ON tbl_studio_room (studio_profile_id, slot_index)
    WHERE archived_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_studio_room_owner_list
    ON tbl_studio_room (studio_profile_id, archived_at, slot_index, id);

CREATE TABLE IF NOT EXISTS tbl_studio_room_feature (
    id uuid NOT NULL,
    room_id uuid NOT NULL,
    label varchar(60) NOT NULL,
    order_index integer NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_room_feature PRIMARY KEY (id),
    CONSTRAINT fk_studio_room_feature_room
        FOREIGN KEY (room_id)
        REFERENCES tbl_studio_room (id)
        ON DELETE CASCADE,
    CONSTRAINT uk_studio_room_feature_order UNIQUE (room_id, order_index),
    CONSTRAINT uk_studio_room_feature_label UNIQUE (room_id, label),
    CONSTRAINT ck_studio_room_feature_order CHECK (order_index BETWEEN 0 AND 7),
    CONSTRAINT ck_studio_room_feature_label_not_blank CHECK (btrim(label) <> '')
);

CREATE TABLE IF NOT EXISTS tbl_studio_room_photo (
    id uuid NOT NULL,
    room_id uuid NOT NULL,
    media_asset_id uuid NOT NULL,
    order_index integer NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_room_photo PRIMARY KEY (id),
    CONSTRAINT fk_studio_room_photo_room
        FOREIGN KEY (room_id)
        REFERENCES tbl_studio_room (id)
        ON DELETE CASCADE,
    CONSTRAINT fk_studio_room_photo_media
        FOREIGN KEY (media_asset_id)
        REFERENCES tbl_media_asset (id)
        ON DELETE RESTRICT,
    CONSTRAINT uk_studio_room_photo_order UNIQUE (room_id, order_index),
    CONSTRAINT uk_studio_room_photo_asset UNIQUE (room_id, media_asset_id),
    CONSTRAINT ck_studio_room_photo_order CHECK (order_index BETWEEN 0 AND 9)
);

CREATE INDEX IF NOT EXISTS idx_studio_room_photo_media
    ON tbl_studio_room_photo (media_asset_id);

CREATE TABLE IF NOT EXISTS tbl_studio_room_reservation (
    id uuid NOT NULL,
    room_id uuid NOT NULL,
    requester_id uuid NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    status varchar(32) NOT NULL,
    approval_required_snapshot boolean NOT NULL,
    hourly_price_minor_snapshot bigint,
    total_price_minor_snapshot bigint,
    currency_snapshot varchar(3) NOT NULL,
    contact_phone_snapshot varchar(16),
    client_request_id uuid NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_room_reservation PRIMARY KEY (id),
    CONSTRAINT fk_studio_room_reservation_room
        FOREIGN KEY (room_id) REFERENCES tbl_studio_room (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_reservation_requester
        FOREIGN KEY (requester_id) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_reservation_decider
        FOREIGN KEY (decided_by) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_reservation_canceller
        FOREIGN KEY (cancelled_by) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT uk_studio_room_reservation_client_request
        UNIQUE (requester_id, client_request_id),
    CONSTRAINT ck_studio_room_reservation_range CHECK (starts_at < ends_at),
    CONSTRAINT ck_studio_room_reservation_duration CHECK (
        extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 14400
        AND mod(extract(epoch FROM (ends_at - starts_at)), 3600) = 0
    ),
    CONSTRAINT ck_studio_room_reservation_status CHECK (status IN (
        'PENDING_APPROVAL', 'CONFIRMED', 'REJECTED_BY_STUDIO',
        'CANCELLED_BY_CUSTOMER', 'CANCELLED_BY_STUDIO', 'EXPIRED'
    )),
    CONSTRAINT ck_studio_room_reservation_price CHECK (
        hourly_price_minor_snapshot IS NULL
        OR hourly_price_minor_snapshot BETWEEN 1 AND 100000000
    ),
    CONSTRAINT ck_studio_room_reservation_total_price CHECK (
        total_price_minor_snapshot IS NULL
        OR total_price_minor_snapshot BETWEEN 1 AND 400000000
    ),
    CONSTRAINT ck_studio_room_reservation_pricing_snapshot CHECK (
        (hourly_price_minor_snapshot IS NULL AND total_price_minor_snapshot IS NULL)
        OR (
            hourly_price_minor_snapshot IS NOT NULL
            AND total_price_minor_snapshot = hourly_price_minor_snapshot
                * (extract(epoch FROM (ends_at - starts_at))::bigint / 3600)
        )
    ),
    CONSTRAINT ck_studio_room_reservation_currency CHECK (
        currency_snapshot ~ '^[A-Z]{3}$'
    ),
    CONSTRAINT ck_studio_room_reservation_state_shape CHECK (
        (decided_at IS NULL) = (decided_by IS NULL)
        AND (cancelled_at IS NULL) = (cancelled_by IS NULL)
        AND (status <> 'PENDING_APPROVAL' OR (
            approval_required_snapshot AND decided_at IS NULL AND cancelled_at IS NULL
        ))
        AND (status <> 'CONFIRMED' OR cancelled_at IS NULL)
        AND (status <> 'REJECTED_BY_STUDIO' OR (
            decided_at IS NOT NULL AND cancelled_at IS NULL
        ))
        AND (status NOT IN ('CANCELLED_BY_CUSTOMER', 'CANCELLED_BY_STUDIO')
            OR cancelled_at IS NOT NULL)
    ),
    CONSTRAINT ck_studio_room_reservation_version CHECK (version >= 0),
    CONSTRAINT ex_studio_room_reservation_requester_overlap
        EXCLUDE USING gist (
            requester_id WITH =,
            room_id WITH =,
            tstzrange(starts_at, ends_at, '[)') WITH &&
        ) WHERE (status IN ('PENDING_APPROVAL', 'CONFIRMED'))
);

CREATE INDEX IF NOT EXISTS idx_studio_room_reservation_schedule
    ON tbl_studio_room_reservation (room_id, status, starts_at, id);

CREATE INDEX IF NOT EXISTS idx_studio_room_reservation_requester
    ON tbl_studio_room_reservation (requester_id, status, starts_at DESC, id);

-- Schedule and customer-history reads do not always filter by status. Keep
-- matching indexes so PostgreSQL can range/ordered-scan instead of sorting a
-- Studio's or requester's complete reservation history.
CREATE INDEX IF NOT EXISTS idx_studio_room_reservation_room_time
    ON tbl_studio_room_reservation (room_id, starts_at, id);

CREATE INDEX IF NOT EXISTS idx_studio_room_reservation_requester_time
    ON tbl_studio_room_reservation (requester_id, starts_at DESC, id);

-- Do not round fractional seconds before checking the whole-hour contract.
-- Recreate this constraint on reruns so release-candidate schemas with the
-- earlier bigint cast are repaired as well.
ALTER TABLE tbl_studio_room_reservation
    DROP CONSTRAINT IF EXISTS ck_studio_room_reservation_duration;
ALTER TABLE tbl_studio_room_reservation
    ADD CONSTRAINT ck_studio_room_reservation_duration CHECK (
        extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 14400
        AND mod(extract(epoch FROM (ends_at - starts_at)), 3600) = 0
    );

-- Different customers may submit overlapping approval requests, but one
-- customer cannot spam the same room/time with fresh idempotency keys. The
-- application opportunistically materializes already-started pending requests
-- as EXPIRED before inserting a new request.
UPDATE tbl_studio_room_reservation
   SET status = 'EXPIRED',
       updated_at = CURRENT_TIMESTAMP,
       version = version + 1
 WHERE status = 'PENDING_APPROVAL'
   AND starts_at <= CURRENT_TIMESTAMP;

-- A database upgraded from a build predating the requester-overlap invariant
-- may already contain duplicate future requests. Preserve every confirmed
-- booking and greedily retain pending candidates in original creation order.
-- Each candidate is compared only with pending rows that actually survived;
-- this matters for an A--B--C interval chain where A and C do not overlap:
-- B is expired while both A and C remain pending. A simple self-join against
-- every earlier row would incorrectly expire C merely because it overlaps B.
--
-- Pending rows that overlap a confirmed booking are always retired. Multiple
-- conflicting confirmed rows are intentionally not rewritten: that indicates
-- corrupt booking data requiring an operator decision, and constraint
-- installation will fail loudly instead of silently cancelling a customer.
-- The repair is skipped entirely once the invariant exists, keeping later
-- migration reruns bounded to the cheap started-pending lifecycle update.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint
         WHERE conrelid = 'tbl_studio_room_reservation'::regclass
           AND conname = 'ex_studio_room_reservation_requester_overlap'
    ) THEN
WITH RECURSIVE pending_candidates AS (
    SELECT reservation.id,
           reservation.requester_id,
           reservation.room_id,
           tstzrange(reservation.starts_at, reservation.ends_at, '[)') AS booking_range,
           row_number() OVER (
               PARTITION BY reservation.requester_id, reservation.room_id
               ORDER BY reservation.created_at, reservation.id
           ) AS sequence_number
      FROM tbl_studio_room_reservation reservation
     WHERE reservation.status = 'PENDING_APPROVAL'
       AND NOT EXISTS (
           SELECT 1
             FROM tbl_studio_room_reservation confirmed
            WHERE confirmed.requester_id = reservation.requester_id
              AND confirmed.room_id = reservation.room_id
              AND confirmed.status = 'CONFIRMED'
              AND tstzrange(confirmed.starts_at, confirmed.ends_at, '[)')
                  && tstzrange(reservation.starts_at, reservation.ends_at, '[)')
       )
), survivor_walk AS (
    SELECT candidate.id,
           candidate.requester_id,
           candidate.room_id,
           candidate.sequence_number,
           ARRAY[candidate.booking_range] AS kept_ranges,
           true AS keep_candidate
      FROM pending_candidates candidate
     WHERE candidate.sequence_number = 1

    UNION ALL

    SELECT candidate.id,
           candidate.requester_id,
           candidate.room_id,
           candidate.sequence_number,
           CASE
               WHEN candidate.booking_range && ANY (walk.kept_ranges)
                   THEN walk.kept_ranges
               ELSE array_append(walk.kept_ranges, candidate.booking_range)
           END AS kept_ranges,
           NOT (candidate.booking_range && ANY (walk.kept_ranges)) AS keep_candidate
      FROM survivor_walk walk
      JOIN pending_candidates candidate
        ON candidate.requester_id = walk.requester_id
       AND candidate.room_id = walk.room_id
       AND candidate.sequence_number = walk.sequence_number + 1
), pending_to_expire AS (
    SELECT reservation.id
      FROM tbl_studio_room_reservation reservation
     WHERE reservation.status = 'PENDING_APPROVAL'
       AND (
           EXISTS (
               SELECT 1
                 FROM tbl_studio_room_reservation confirmed
                WHERE confirmed.requester_id = reservation.requester_id
                  AND confirmed.room_id = reservation.room_id
                  AND confirmed.status = 'CONFIRMED'
                  AND tstzrange(confirmed.starts_at, confirmed.ends_at, '[)')
                      && tstzrange(reservation.starts_at, reservation.ends_at, '[)')
           )
           OR EXISTS (
               SELECT 1
                 FROM survivor_walk walk
                WHERE walk.id = reservation.id
                  AND NOT walk.keep_candidate
           )
       )
)
UPDATE tbl_studio_room_reservation reservation
   SET status = 'EXPIRED',
       updated_at = CURRENT_TIMESTAMP,
       version = reservation.version + 1
  FROM pending_to_expire expired
 WHERE reservation.id = expired.id;

        ALTER TABLE tbl_studio_room_reservation
            ADD CONSTRAINT ex_studio_room_reservation_requester_overlap
            EXCLUDE USING gist (
                requester_id WITH =,
                room_id WITH =,
                tstzrange(starts_at, ends_at, '[)') WITH &&
            ) WHERE (status IN ('PENDING_APPROVAL', 'CONFIRMED'));
    END IF;
END
$$;

CREATE TABLE IF NOT EXISTS tbl_studio_room_occupancy (
    id uuid NOT NULL,
    room_id uuid NOT NULL,
    reservation_id uuid,
    client_request_id uuid,
    type varchar(24) NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    active boolean NOT NULL DEFAULT true,
    created_by uuid NOT NULL,
    released_at timestamp with time zone,
    released_by uuid,
    release_reason varchar(200),
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_room_occupancy PRIMARY KEY (id),
    CONSTRAINT fk_studio_room_occupancy_room
        FOREIGN KEY (room_id) REFERENCES tbl_studio_room (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_occupancy_reservation
        FOREIGN KEY (reservation_id) REFERENCES tbl_studio_room_reservation (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_occupancy_creator
        FOREIGN KEY (created_by) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_room_occupancy_releaser
        FOREIGN KEY (released_by) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT uk_studio_room_occupancy_reservation UNIQUE (reservation_id),
    CONSTRAINT ck_studio_room_occupancy_type CHECK (type IN ('RESERVATION', 'MANUAL_BLOCK')),
    CONSTRAINT ck_studio_room_occupancy_shape CHECK (
        (type = 'RESERVATION' AND reservation_id IS NOT NULL AND client_request_id IS NULL)
        OR (type = 'MANUAL_BLOCK' AND reservation_id IS NULL AND client_request_id IS NOT NULL)
    ),
    CONSTRAINT ck_studio_room_occupancy_range CHECK (starts_at < ends_at),
    CONSTRAINT ck_studio_room_occupancy_duration CHECK (
        mod(extract(epoch FROM (ends_at - starts_at)), 3600) = 0
        AND (
            (type = 'RESERVATION'
                AND extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 14400)
            OR
            (type = 'MANUAL_BLOCK'
                AND extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 50400)
        )
    ),
    CONSTRAINT ck_studio_room_occupancy_release CHECK (
        (active AND released_at IS NULL AND released_by IS NULL)
        OR (NOT active AND released_at IS NOT NULL AND released_by IS NOT NULL)
    ),
    CONSTRAINT ck_studio_room_occupancy_version CHECK (version >= 0),
    CONSTRAINT ex_studio_room_occupancy_no_overlap
        EXCLUDE USING gist (
            room_id WITH =,
            tstzrange(starts_at, ends_at, '[)') WITH &&
        ) WHERE (active)
);

-- Hibernate may have created the table before this migration was introduced.
-- CREATE TABLE IF NOT EXISTS does not backfill constraints on such a table, so
-- install the database-level room-overlap invariant explicitly on every legacy
-- schema. Existing conflicting active rows are intentionally not rewritten:
-- constraint installation must fail closed and require an operator decision.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint
         WHERE conrelid = 'tbl_studio_room_occupancy'::regclass
           AND conname = 'ex_studio_room_occupancy_no_overlap'
    ) THEN
        ALTER TABLE tbl_studio_room_occupancy
            ADD CONSTRAINT ex_studio_room_occupancy_no_overlap
            EXCLUDE USING gist (
                room_id WITH =,
                tstzrange(starts_at, ends_at, '[)') WITH &&
            ) WHERE (active);
    END IF;
END
$$;

CREATE INDEX IF NOT EXISTS idx_studio_room_occupancy_schedule
    ON tbl_studio_room_occupancy (room_id, active, starts_at, id);

CREATE UNIQUE INDEX IF NOT EXISTS uk_studio_occupancy_manual_client_request
    ON tbl_studio_room_occupancy (created_by, client_request_id)
    WHERE client_request_id IS NOT NULL;

-- Earlier release candidates applied the customer reservation limit (four
-- hours) to every occupancy kind. Owner-created blocks intentionally cover up
-- to the complete 09:00..23:00 operating day, so repair that constraint on a
-- rerun while preserving the stricter reservation limit.
ALTER TABLE tbl_studio_room_occupancy
    DROP CONSTRAINT IF EXISTS ck_studio_room_occupancy_duration;
ALTER TABLE tbl_studio_room_occupancy
    ADD CONSTRAINT ck_studio_room_occupancy_duration CHECK (
        mod(extract(epoch FROM (ends_at - starts_at)), 3600) = 0
        AND (
            (type = 'RESERVATION'
                AND extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 14400)
            OR
            (type = 'MANUAL_BLOCK'
                AND extract(epoch FROM (ends_at - starts_at)) BETWEEN 3600 AND 50400)
        )
    );

CREATE OR REPLACE FUNCTION soundconnect_validate_reservation_occupancy()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    reservation_room uuid;
    reservation_status varchar(32);
    reservation_starts_at timestamp with time zone;
    reservation_ends_at timestamp with time zone;
BEGIN
    IF NEW.type = 'MANUAL_BLOCK' THEN
        RETURN NEW;
    END IF;

    SELECT room_id, status, starts_at, ends_at
      INTO reservation_room, reservation_status,
           reservation_starts_at, reservation_ends_at
      FROM tbl_studio_room_reservation
     WHERE id = NEW.reservation_id;

    IF reservation_room IS NULL
       OR reservation_room <> NEW.room_id
       OR reservation_status <> 'CONFIRMED'
       OR reservation_starts_at <> NEW.starts_at
       OR reservation_ends_at <> NEW.ends_at THEN
        RAISE EXCEPTION 'reservation occupancy must match a confirmed reservation in the same room and time window'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_studio_room_occupancy_reservation_match';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_studio_room_occupancy_reservation
    ON tbl_studio_room_occupancy;
CREATE TRIGGER trg_studio_room_occupancy_reservation
BEFORE INSERT OR UPDATE OF room_id, reservation_id, type, starts_at, ends_at
ON tbl_studio_room_occupancy
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_reservation_occupancy();

-- ---------------------------------------------------------------------------
-- Equipment inventory, ordered attachments and daily availability projection
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tbl_studio_equipment (
    id uuid NOT NULL,
    studio_profile_id uuid NOT NULL,
    creation_client_request_id uuid NOT NULL,
    creation_payload_hash varchar(64) NOT NULL,
    category_id uuid NOT NULL,
    name varchar(100) NOT NULL,
    brand varchar(60),
    model varchar(60),
    description varchar(300),
    total_quantity integer NOT NULL,
    archived_at timestamp with time zone,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_equipment PRIMARY KEY (id),
    CONSTRAINT fk_studio_equipment_profile
        FOREIGN KEY (studio_profile_id) REFERENCES tbl_studio_profile (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_equipment_category
        FOREIGN KEY (category_id) REFERENCES tbl_backline_category (id) ON DELETE RESTRICT,
    CONSTRAINT uk_studio_equipment_create_request
        UNIQUE (studio_profile_id, creation_client_request_id),
    CONSTRAINT ck_studio_equipment_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_studio_equipment_creation_payload_hash
        CHECK (creation_payload_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_studio_equipment_total_quantity CHECK (total_quantity BETWEEN 1 AND 999),
    CONSTRAINT ck_studio_equipment_version CHECK (version >= 0)
);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_studio_active
    ON tbl_studio_equipment (studio_profile_id, archived_at);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_category
    ON tbl_studio_equipment (category_id);

CREATE OR REPLACE FUNCTION soundconnect_validate_studio_equipment_category()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    category_level smallint;
    category_active boolean;
BEGIN
    SELECT level, active INTO category_level, category_active
      FROM tbl_backline_category
     WHERE id = NEW.category_id;

    IF category_level IS NULL OR category_level <> 1 OR NOT category_active THEN
        RAISE EXCEPTION 'studio equipment must reference an active leaf category'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_studio_equipment_leaf_category';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_studio_equipment_category ON tbl_studio_equipment;
CREATE TRIGGER trg_studio_equipment_category
BEFORE INSERT OR UPDATE OF category_id ON tbl_studio_equipment
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_studio_equipment_category();

CREATE TABLE IF NOT EXISTS tbl_studio_equipment_feature (
    id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    position integer NOT NULL,
    label varchar(60) NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_equipment_feature PRIMARY KEY (id),
    CONSTRAINT fk_studio_equipment_feature_equipment
        FOREIGN KEY (equipment_id) REFERENCES tbl_studio_equipment (id) ON DELETE CASCADE,
    CONSTRAINT uk_studio_equipment_feature_position UNIQUE (equipment_id, position),
    CONSTRAINT uk_studio_equipment_feature_label UNIQUE (equipment_id, label),
    CONSTRAINT ck_studio_equipment_feature_position CHECK (position BETWEEN 0 AND 11),
    CONSTRAINT ck_studio_equipment_feature_label_not_blank CHECK (btrim(label) <> '')
);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_feature_equipment
    ON tbl_studio_equipment_feature (equipment_id);

CREATE TABLE IF NOT EXISTS tbl_studio_equipment_photo (
    id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    position integer NOT NULL,
    media_asset_id uuid NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_equipment_photo PRIMARY KEY (id),
    CONSTRAINT fk_studio_equipment_photo_equipment
        FOREIGN KEY (equipment_id) REFERENCES tbl_studio_equipment (id) ON DELETE CASCADE,
    CONSTRAINT fk_studio_equipment_photo_media
        FOREIGN KEY (media_asset_id) REFERENCES tbl_media_asset (id) ON DELETE RESTRICT,
    CONSTRAINT uk_studio_equipment_photo_position UNIQUE (equipment_id, position),
    CONSTRAINT uk_studio_equipment_photo_asset UNIQUE (equipment_id, media_asset_id),
    CONSTRAINT ck_studio_equipment_photo_position CHECK (position BETWEEN 0 AND 4)
);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_photo_media
    ON tbl_studio_equipment_photo (media_asset_id);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_photo_equipment
    ON tbl_studio_equipment_photo (equipment_id);

CREATE TABLE IF NOT EXISTS tbl_studio_equipment_day (
    id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    availability_date date NOT NULL,
    busy_count integer NOT NULL DEFAULT 0,
    maintenance_count integer NOT NULL DEFAULT 0,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_equipment_day PRIMARY KEY (id),
    CONSTRAINT fk_studio_equipment_day_equipment
        FOREIGN KEY (equipment_id) REFERENCES tbl_studio_equipment (id) ON DELETE CASCADE,
    CONSTRAINT uk_studio_equipment_day UNIQUE (equipment_id, availability_date),
    CONSTRAINT ck_studio_equipment_day_counts
        CHECK (busy_count >= 0 AND maintenance_count >= 0),
    CONSTRAINT ck_studio_equipment_day_non_default
        CHECK (busy_count + maintenance_count > 0),
    CONSTRAINT ck_studio_equipment_day_version CHECK (version >= 0)
);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_day_range
    ON tbl_studio_equipment_day (equipment_id, availability_date);

CREATE TABLE IF NOT EXISTS tbl_studio_equipment_availability_change (
    id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    source_bucket varchar(16) NOT NULL,
    target_bucket varchar(16) NOT NULL,
    quantity integer NOT NULL,
    client_request_id uuid NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_studio_equipment_availability_change PRIMARY KEY (id),
    CONSTRAINT fk_studio_equipment_change_equipment
        FOREIGN KEY (equipment_id) REFERENCES tbl_studio_equipment (id) ON DELETE RESTRICT,
    CONSTRAINT fk_studio_equipment_change_actor
        FOREIGN KEY (actor_id) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT uk_studio_equipment_availability_request
        UNIQUE (equipment_id, client_request_id),
    CONSTRAINT ck_studio_equipment_change_range CHECK (start_date <= end_date),
    CONSTRAINT ck_studio_equipment_change_buckets CHECK (
        source_bucket IN ('AVAILABLE', 'BUSY', 'MAINTENANCE')
        AND target_bucket IN ('AVAILABLE', 'BUSY', 'MAINTENANCE')
        AND source_bucket <> target_bucket
    ),
    CONSTRAINT ck_studio_equipment_change_quantity CHECK (quantity BETWEEN 1 AND 999)
);

CREATE INDEX IF NOT EXISTS idx_studio_equipment_change_history
    ON tbl_studio_equipment_availability_change (equipment_id, created_at);

-- Day rows are mutable calendar projections, not audit records. The immutable
-- change table above retains history, so expired projections can be removed.
-- The application repeats this cleanup opportunistically under the equipment
-- lock on successful owner writes, keeping active calendars bounded to the
-- supported 730-day horizon.
DELETE FROM tbl_studio_equipment_day day
USING tbl_studio_equipment equipment, tbl_studio_profile studio
WHERE day.equipment_id = equipment.id
  AND equipment.studio_profile_id = studio.id
  AND day.availability_date
      < (CURRENT_TIMESTAMP AT TIME ZONE studio.time_zone)::date;

CREATE OR REPLACE FUNCTION soundconnect_validate_studio_equipment_day_capacity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    equipment_capacity integer;
    equipment_archived_at timestamp with time zone;
BEGIN
    SELECT total_quantity, archived_at
      INTO equipment_capacity, equipment_archived_at
     FROM tbl_studio_equipment
     WHERE id = NEW.equipment_id
     FOR UPDATE;

    IF equipment_capacity IS NULL THEN
        RAISE EXCEPTION 'studio equipment does not exist'
            USING ERRCODE = '23503';
    END IF;
    IF equipment_archived_at IS NOT NULL THEN
        RAISE EXCEPTION 'archived studio equipment calendar cannot be changed'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_studio_equipment_day_active_equipment';
    END IF;
    IF NEW.busy_count + NEW.maintenance_count > equipment_capacity THEN
        RAISE EXCEPTION 'equipment day allocation exceeds total quantity'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_studio_equipment_day_capacity';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_studio_equipment_day_capacity
    ON tbl_studio_equipment_day;
CREATE TRIGGER trg_studio_equipment_day_capacity
BEFORE INSERT OR UPDATE OF equipment_id, busy_count, maintenance_count
ON tbl_studio_equipment_day
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_studio_equipment_day_capacity();

CREATE OR REPLACE FUNCTION soundconnect_validate_studio_equipment_total_quantity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    studio_local_today date;
BEGIN
    SELECT (CURRENT_TIMESTAMP AT TIME ZONE studio.time_zone)::date
      INTO studio_local_today
      FROM tbl_studio_profile studio
     WHERE studio.id = NEW.studio_profile_id;

    IF studio_local_today IS NULL THEN
        RAISE EXCEPTION 'studio profile does not exist'
            USING ERRCODE = '23503';
    END IF;

    IF NEW.total_quantity < OLD.total_quantity
       AND EXISTS (
           SELECT 1
             FROM tbl_studio_equipment_day day
            WHERE day.equipment_id = NEW.id
              AND day.availability_date >= studio_local_today
              AND day.busy_count + day.maintenance_count > NEW.total_quantity
       ) THEN
        RAISE EXCEPTION 'equipment total quantity is below a current or future day allocation'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_studio_equipment_total_covers_calendar';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_studio_equipment_total_quantity
    ON tbl_studio_equipment;
CREATE TRIGGER trg_studio_equipment_total_quantity
BEFORE UPDATE OF total_quantity ON tbl_studio_equipment
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_studio_equipment_total_quantity();

-- ---------------------------------------------------------------------------
-- Owner catalog requests and proposed root children
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tbl_backline_category_request (
    id uuid NOT NULL,
    studio_profile_id uuid NOT NULL,
    requested_by_user_id uuid NOT NULL,
    client_request_id uuid NOT NULL,
    request_payload_hash varchar(64) NOT NULL,
    request_type varchar(24) NOT NULL,
    requested_name varchar(160) NOT NULL,
    normalized_requested_name varchar(160) NOT NULL,
    requester_note varchar(300),
    parent_category_id uuid,
    status varchar(16) NOT NULL DEFAULT 'PENDING',
    reviewed_by_user_id uuid,
    reviewed_at timestamp with time zone,
    decision_note varchar(500),
    resolved_root_category_id uuid,
    resolved_category_id uuid,
    version bigint NOT NULL DEFAULT 0,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_backline_category_request PRIMARY KEY (id),
    CONSTRAINT fk_backline_category_request_studio
        FOREIGN KEY (studio_profile_id) REFERENCES tbl_studio_profile (id) ON DELETE RESTRICT,
    CONSTRAINT fk_backline_category_request_requester
        FOREIGN KEY (requested_by_user_id) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_backline_category_request_parent
        FOREIGN KEY (parent_category_id) REFERENCES tbl_backline_category (id) ON DELETE RESTRICT,
    CONSTRAINT fk_backline_category_request_reviewer
        FOREIGN KEY (reviewed_by_user_id) REFERENCES tbl_user (id) ON DELETE RESTRICT,
    CONSTRAINT fk_backline_category_request_resolved_root
        FOREIGN KEY (resolved_root_category_id) REFERENCES tbl_backline_category (id) ON DELETE RESTRICT,
    CONSTRAINT fk_backline_category_request_resolved_category
        FOREIGN KEY (resolved_category_id) REFERENCES tbl_backline_category (id) ON DELETE RESTRICT,
    CONSTRAINT uk_backline_category_request_client
        UNIQUE (studio_profile_id, client_request_id),
    CONSTRAINT ck_backline_category_request_payload_hash
        CHECK (request_payload_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_backline_category_request_type
        CHECK (request_type IN ('ROOT_CATEGORY', 'SUBCATEGORY')),
    CONSTRAINT ck_backline_category_request_shape CHECK (
        (request_type = 'ROOT_CATEGORY' AND parent_category_id IS NULL)
        OR (request_type = 'SUBCATEGORY' AND parent_category_id IS NOT NULL)
    ),
    CONSTRAINT ck_backline_category_request_name CHECK (
        btrim(requested_name) <> '' AND btrim(normalized_requested_name) <> ''
    ),
    CONSTRAINT ck_backline_category_request_note CHECK (
        requester_note IS NULL OR btrim(requester_note) <> ''
    ),
    CONSTRAINT ck_backline_category_request_status CHECK (
        status IN ('PENDING', 'APPROVED', 'REJECTED', 'WITHDRAWN')
    ),
    CONSTRAINT ck_backline_category_request_decision CHECK (
        (status = 'PENDING'
            AND reviewed_by_user_id IS NULL AND reviewed_at IS NULL
            AND resolved_root_category_id IS NULL AND resolved_category_id IS NULL)
        OR (status = 'APPROVED'
            AND reviewed_by_user_id IS NOT NULL AND reviewed_at IS NOT NULL
            AND resolved_root_category_id IS NOT NULL AND resolved_category_id IS NOT NULL)
        OR (status = 'REJECTED'
            AND reviewed_by_user_id IS NOT NULL AND reviewed_at IS NOT NULL
            AND resolved_root_category_id IS NULL AND resolved_category_id IS NULL)
        OR (status = 'WITHDRAWN'
            AND reviewed_by_user_id IS NULL AND reviewed_at IS NULL
            AND resolved_root_category_id IS NULL AND resolved_category_id IS NULL)
    ),
    CONSTRAINT ck_backline_category_request_version CHECK (version >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_backline_category_request_pending_equivalent
    ON tbl_backline_category_request (
        studio_profile_id,
        request_type,
        coalesce(parent_category_id, '00000000-0000-0000-0000-000000000000'::uuid),
        normalized_requested_name
    )
    WHERE status = 'PENDING';

CREATE INDEX IF NOT EXISTS idx_backline_request_studio_status
    ON tbl_backline_category_request (studio_profile_id, status, created_at);

CREATE INDEX IF NOT EXISTS idx_backline_request_admin_status
    ON tbl_backline_category_request (status, created_at);

CREATE INDEX IF NOT EXISTS idx_backline_request_studio_created
    ON tbl_backline_category_request (studio_profile_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS idx_backline_request_admin_created
    ON tbl_backline_category_request (created_at DESC, id DESC);

CREATE OR REPLACE FUNCTION soundconnect_validate_backline_category_request_parent()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    parent_level smallint;
    parent_active boolean;
BEGIN
    IF NEW.request_type = 'ROOT_CATEGORY' THEN
        RETURN NEW;
    END IF;

    SELECT level, active INTO parent_level, parent_active
      FROM tbl_backline_category
     WHERE id = NEW.parent_category_id;

    IF parent_level IS NULL OR parent_level <> 0 OR NOT parent_active THEN
        RAISE EXCEPTION 'subcategory request requires an active root category'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_request_active_root';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_backline_category_request_parent
    ON tbl_backline_category_request;
CREATE TRIGGER trg_backline_category_request_parent
BEFORE INSERT OR UPDATE OF request_type, parent_category_id
ON tbl_backline_category_request
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_backline_category_request_parent();

CREATE TABLE IF NOT EXISTS tbl_backline_category_request_child (
    id uuid NOT NULL,
    request_id uuid NOT NULL,
    position integer NOT NULL,
    name varchar(160) NOT NULL,
    normalized_name varchar(160) NOT NULL,
    resolved_category_id uuid,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_backline_category_request_child PRIMARY KEY (id),
    CONSTRAINT fk_backline_category_request_child_request
        FOREIGN KEY (request_id) REFERENCES tbl_backline_category_request (id) ON DELETE CASCADE,
    CONSTRAINT fk_backline_category_request_child_result
        FOREIGN KEY (resolved_category_id) REFERENCES tbl_backline_category (id) ON DELETE RESTRICT,
    CONSTRAINT uk_backline_request_child_position UNIQUE (request_id, position),
    CONSTRAINT uk_backline_request_child_name UNIQUE (request_id, normalized_name),
    CONSTRAINT ck_backline_category_request_child_position CHECK (position BETWEEN 0 AND 9),
    CONSTRAINT ck_backline_category_request_child_name CHECK (
        btrim(name) <> '' AND btrim(normalized_name) <> ''
    )
);

CREATE INDEX IF NOT EXISTS idx_backline_request_child_request
    ON tbl_backline_category_request_child (request_id);

CREATE OR REPLACE FUNCTION soundconnect_validate_backline_request_child()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    parent_request_type varchar(24);
    request_status varchar(16);
BEGIN
    SELECT request_type, status INTO parent_request_type, request_status
      FROM tbl_backline_category_request
     WHERE id = NEW.request_id;

    IF parent_request_type IS NULL OR parent_request_type <> 'ROOT_CATEGORY' THEN
        RAISE EXCEPTION 'proposed children belong only to pending root category requests'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_request_child_parent';
    END IF;

    IF TG_OP = 'INSERT' AND request_status <> 'PENDING' THEN
        RAISE EXCEPTION 'new proposed children belong only to pending root category requests'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_request_child_parent';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.request_id IS DISTINCT FROM OLD.request_id
           OR NEW.position IS DISTINCT FROM OLD.position
           OR NEW.name IS DISTINCT FROM OLD.name
           OR NEW.normalized_name IS DISTINCT FROM OLD.normalized_name THEN
            RAISE EXCEPTION 'proposed child identity is immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_request_child_immutable';
        END IF;
        IF request_status NOT IN ('PENDING', 'APPROVED') THEN
            RAISE EXCEPTION 'only pending or approved requests can resolve proposed children'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_backline_category_request_child_parent';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_backline_category_request_child
    ON tbl_backline_category_request_child;
CREATE TRIGGER trg_backline_category_request_child
BEFORE INSERT OR UPDATE
ON tbl_backline_category_request_child
FOR EACH ROW
EXECUTE FUNCTION soundconnect_validate_backline_request_child();

-- Permission UUID is stable and does not depend on pgcrypto.
INSERT INTO tbl_permissions (id, name, created_at, updated_at)
VALUES
    ('9a0a90ca-811f-4e09-9f50-9dd4c357334b', 'MANAGE_BACKLINE_CATALOG', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('72e544d9-c278-4ef8-86cd-d32b528689d5', 'MANAGE_STUDIO_APPLICATIONS', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT (name) DO NOTHING;

-- Runtime bootstrapping can be disabled in production. Grant the new
-- authority during the migration as well so catalog review is usable
-- immediately after deployment. ROLE_OWNER intentionally mirrors the
-- application's existing "all permissions" policy.
INSERT INTO role_permissions (role_id, permission_id)
SELECT role.id, permission.id
  FROM tbl_role role
  JOIN tbl_permissions permission
    ON permission.name IN ('MANAGE_BACKLINE_CATALOG', 'MANAGE_STUDIO_APPLICATIONS')
 WHERE role.name IN ('ROLE_ADMIN', 'ROLE_OWNER')
   AND NOT EXISTS (
       SELECT 1
         FROM role_permissions existing
        WHERE existing.role_id = role.id
          AND existing.permission_id = permission.id
   )
ON CONFLICT DO NOTHING;

COMMIT;
